beforeExample:
package test;

import org.eclipse.jface.text.TextUtilities;

class Example {
    String[] legalDelimiters = {"\n", "\r\n"};
    String contents = "hello\nworld";

    void test() {
        if (TextUtilities.indexOf(legalDelimiters, contents, 0)[0] != -1) {
            System.out.println("Delimiter found!");
        }
    }
}

afterExample:
package test;

import org.eclipse.jface.text.MultiStringMatcher;
import org.eclipse.jface.text.TextUtilities;

class Example {
    String[] legalDelimiters = {"\n", "\r\n"};
    String contents = "hello\nworld";

    void test() {
        if (MultiStringMatcher.indexOf(contents, 0, legalDelimiters) != null) {
            System.out.println("Delimiter found!");
        }
    }
}

negativeExample:
package test;

import org.eclipse.jface.text.TextUtilities;
import org.eclipse.jface.text.MultiStringMatcher;

class Example {
    String[] legalDelimiters = {"\n", "\r\n"};
    String contents = "hello\nworld";

    void test() {
        // This should not match, as it uses the numeric index directly, not a null check.
        int offset = TextUtilities.indexOf(legalDelimiters, contents, 0)[0];
        if (offset > 0) {
            System.out.println("Offset: " + offset);
        }

        // This should not match, as it uses the delimiter type index (index[1]).
        int delimiterTypeIndex = TextUtilities.indexOf(legalDelimiters, contents, 0)[1];
        if (delimiterTypeIndex != -1) {
            System.out.println("Delimiter kind: " + legalDelimiters[delimiterTypeIndex]);
        }
    }
}
